CREATE TABLE agentsec_operating_unit (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,workshop VARCHAR(60) NOT NULL,planned_capacity INT NOT NULL,active BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE agentsec_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(50) NOT NULL,role VARCHAR(20) NOT NULL,operating_unit_code VARCHAR(32),enabled BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE agentsec_work_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,record_no VARCHAR(32) NOT NULL UNIQUE,subject_code VARCHAR(40) NOT NULL,subject_name VARCHAR(120) NOT NULL,operating_unit_id BIGINT NOT NULL,planned_qty INT NOT NULL,completed_qty INT NOT NULL,defect_qty INT NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,version_no VARCHAR(40),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_order_center FOREIGN KEY(operating_unit_id) REFERENCES agentsec_operating_unit(id));
CREATE TABLE agentsec_activity_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,work_record_id BIGINT NOT NULL,operation_name VARCHAR(50) NOT NULL,good_qty INT NOT NULL,defect_qty INT NOT NULL,operator_name VARCHAR(50) NOT NULL,reported_at DATETIME(6) NOT NULL,remark VARCHAR(200),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_report_order FOREIGN KEY(work_record_id) REFERENCES agentsec_work_record(id));
CREATE TABLE agentsec_review_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,review_record_no VARCHAR(32) NOT NULL UNIQUE,work_record_id BIGINT NOT NULL,review_record_type VARCHAR(30) NOT NULL,review_record_qty INT NOT NULL,defect_qty INT NOT NULL,result VARCHAR(20) NOT NULL,inspector VARCHAR(50),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_inspection_order FOREIGN KEY(work_record_id) REFERENCES agentsec_work_record(id));
CREATE TABLE agentsec_resource_register (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,operating_unit_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,oee INT NOT NULL,last_heartbeat DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_equipment_center FOREIGN KEY(operating_unit_id) REFERENCES agentsec_operating_unit(id));
CREATE INDEX idx_order_status_due ON agentsec_work_record(status,due_date); CREATE INDEX idx_report_order_time ON agentsec_activity_record(work_record_id,reported_at); CREATE INDEX idx_equipment_status ON agentsec_resource_register(status);
